-- =====================================================================
-- 007 · Ejercicios para las 4 patas (Ep 1–3)
--   - Tipos nuevos: comprension (escucha o lee y responde), decir (dilo en voz alta),
--     libre (escríbelo libre, lo califica Wako en el Paso 7) y rapido (ronda contra reloj).
--   - "banco-epN": ejercicios de práctica por tema y pata (los usa "Mi camino").
--   - "examen-epN": banco RESERVADO, solo sale en exámenes (reservado = true).
--   - Llena los temas que estaban vacíos: this/that, the, números y la hora.
-- Pega TODO este archivo en Supabase → SQL Editor → Run.
-- Se puede correr varias veces sin dañar nada. Requiere haber corrido el 006.
-- =====================================================================

alter table lecciones drop constraint if exists lecciones_tipo_check;
alter table lecciones add constraint lecciones_tipo_check check (tipo in ('refuerzo','tema','simulacro','banco','examen'));
alter table ejercicios drop constraint if exists ejercicios_tipo_check;
alter table ejercicios add constraint ejercicios_tipo_check
  check (tipo in ('elegir','escuchar','ordenar','escribir','emparejar','comprension','decir','libre','rapido'));
alter table ejercicios add column if not exists reservado boolean not null default false;

-- ============ BANCOS (no aparecen en la lista de lecciones) ============
on conflict (id) do update set unidad_id = excluded.unidad_id, episodio = excluded.episodio, orden = excluded.orden,
  tipo = excluded.tipo, titulo = excluded.titulo, descripcion = excluded.descripcion;

-- ============ EJERCICIOS ============
on conflict (id) do update set leccion_id = excluded.leccion_id, orden = excluded.orden, tipo = excluded.tipo, datos = excluded.datos,
  tema_id = excluded.tema_id, pata = excluded.pata, reservado = excluded.reservado;
on conflict (id) do update set leccion_id = excluded.leccion_id, orden = excluded.orden, tipo = excluded.tipo, datos = excluded.datos,
  tema_id = excluded.tema_id, pata = excluded.pata, reservado = excluded.reservado;
on conflict (id) do update set leccion_id = excluded.leccion_id, orden = excluded.orden, tipo = excluded.tipo, datos = excluded.datos,
  tema_id = excluded.tema_id, pata = excluded.pata, reservado = excluded.reservado;
on conflict (id) do update set leccion_id = excluded.leccion_id, orden = excluded.orden, tipo = excluded.tipo, datos = excluded.datos,
  tema_id = excluded.tema_id, pata = excluded.pata, reservado = excluded.reservado;
on conflict (id) do update set leccion_id = excluded.leccion_id, orden = excluded.orden, tipo = excluded.tipo, datos = excluded.datos,
  tema_id = excluded.tema_id, pata = excluded.pata, reservado = excluded.reservado;

-- Listo: 258 ejercicios nuevos (16 estudio, 44 input, 66 output, 66 fluidez + 66 reservados para exámenes).
