insert into ejercicios (id, leccion_id, orden, tipo, datos, tema_id, pata, reservado) values
  ('banco-ep1-to-be-01', 'banco-ep1', 1, 'comprension', '{"modo": "escuchar", "lineas": [{"en": "Hi, I''m Ana.", "es": "Hola, soy Ana."}, {"en": "I''m a teacher.", "es": "Soy profesora."}, {"en": "My students are very nice.", "es": "Mis estudiantes son muy amables."}], "pregunta": "What is Ana''s job?", "pregunta_es": "¿Cuál es el trabajo de Ana?", "opciones": ["She is a teacher.", "She is a student.", "She is a nurse."], "correcta": 0, "explicacion": "\"I''m a teacher\" = Soy profesora. I''m = I am."}'::jsonb, 'ep1-to-be', 'input', false),
  ('banco-ep1-to-be-02', 'banco-ep1', 2, 'comprension', '{"modo": "leer", "lineas": [{"en": "Pedro and Luis are brothers.", "es": "Pedro y Luis son hermanos."}, {"en": "They are from Cúcuta.", "es": "Son de Cúcuta."}, {"en": "Pedro is tall, but Luis isn''t.", "es": "Pedro es alto, pero Luis no."}], "pregunta": "Where are they from?", "pregunta_es": "¿De dónde son?", "opciones": ["They are from Cúcuta.", "They are from Bogotá.", "They are brothers."], "correcta": 0, "explicacion": "They are from… = Son de…"}'::jsonb, 'ep1-to-be', 'input', false),
  ('banco-ep1-to-be-03', 'banco-ep1', 3, 'decir', '{"es": "Soy de Colombia.", "respuestas": ["i am from colombia", "im from colombia"], "mostrar": "I''m from Colombia.", "explicacion": "I am = I''m. From = de (origen)."}'::jsonb, 'ep1-to-be', 'output', false),
  ('banco-ep1-to-be-04', 'banco-ep1', 4, 'decir', '{"es": "Mi esposa no está cansada.", "respuestas": ["my wife is not tired", "my wife isnt tired"], "mostrar": "My wife isn''t tired.", "explicacion": "Negativo: is not = isn''t."}'::jsonb, 'ep1-to-be', 'output', false),
  ('banco-ep1-to-be-05', 'banco-ep1', 5, 'libre', '{"pregunta": "Introduce yourself: your name, where you are from and your job.", "pregunta_es": "Preséntate: tu nombre, de dónde eres y a qué te dedicas.", "ejemplo": "Hi, I''m Uwaldo. I''m from Colombia. I''m a businessman.", "criterio": "Usa I''m / I am correctamente; no mezclar am con otro verbo.", "explicacion": "Usa I''m / I am correctamente; no mezclar am con otro verbo."}'::jsonb, 'ep1-to-be', 'output', false),
  ('banco-ep1-to-be-06', 'banco-ep1', 6, 'rapido', '{"frase": "I ___ happy.", "opciones": ["am", "is"], "correcta": 0, "es": "Estoy feliz.", "explicacion": "I → am.", "segundos": 6}'::jsonb, 'ep1-to-be', 'fluidez', false),
  ('banco-ep1-to-be-07', 'banco-ep1', 7, 'rapido', '{"frase": "They ___ at home.", "opciones": ["are", "is"], "correcta": 0, "es": "Están en casa.", "explicacion": "They → are.", "segundos": 6}'::jsonb, 'ep1-to-be', 'fluidez', false),
  ('banco-ep1-to-be-08', 'banco-ep1', 8, 'rapido', '{"frase": "She ___ my sister.", "opciones": ["is", "are"], "correcta": 0, "es": "Ella es mi hermana.", "explicacion": "She → is.", "segundos": 6}'::jsonb, 'ep1-to-be', 'fluidez', false),
  ('examen-ep1-to-be-01', 'examen-ep1', 1, 'elegir', '{"frase": "We ___ from Cúcuta.", "opciones": ["are", "is", "am"], "correcta": 0, "es": "Somos de Cúcuta.", "explicacion": "We → are."}'::jsonb, 'ep1-to-be', 'estudio', true),
  ('examen-ep1-to-be-02', 'examen-ep1', 2, 'escribir', '{"respuestas": ["he is not a doctor", "he isnt a doctor"], "mostrar": "He isn''t a doctor.", "es": "Él no es doctor.", "explicacion": "He is not = he isn''t; profesión con a."}'::jsonb, 'ep1-to-be', 'estudio', true),
  ('examen-ep1-to-be-03', 'examen-ep1', 3, 'elegir', '{"frase": "___ your brother a lawyer? — Yes, he is.", "opciones": ["Is", "Are", "Does"], "correcta": 0, "es": "¿Tu hermano es abogado? — Sí.", "explicacion": "Pregunta con to be: Is + sujeto…?"}'::jsonb, 'ep1-to-be', 'estudio', true),
  ('banco-ep1-a-an-01', 'banco-ep1', 9, 'comprension', '{"modo": "escuchar", "lineas": [{"en": "I have an orange and a banana.", "es": "Tengo una naranja y un banano."}, {"en": "I eat the orange in the morning.", "es": "Me como la naranja en la mañana."}], "pregunta": "What fruit does he eat in the morning?", "pregunta_es": "¿Qué fruta come en la mañana?", "opciones": ["An orange.", "A banana.", "An apple."], "correcta": 0, "explicacion": "an orange: orange empieza con sonido de vocal."}'::jsonb, 'ep1-a-an', 'input', false),
  ('banco-ep1-a-an-02', 'banco-ep1', 10, 'comprension', '{"modo": "leer", "lineas": [{"en": "My friend is an architect.", "es": "Mi amigo es arquitecto."}, {"en": "He has a big office and an old car.", "es": "Tiene una oficina grande y un carro viejo."}], "pregunta": "Complete: He has ___ old car.", "pregunta_es": "Tiene un carro viejo.", "opciones": ["an", "a"], "correcta": 0, "explicacion": "old empieza con sonido de vocal → an old car."}'::jsonb, 'ep1-a-an', 'input', false),
  ('banco-ep1-a-an-03', 'banco-ep1', 11, 'decir', '{"es": "Es una idea interesante.", "respuestas": ["it is an interesting idea", "its an interesting idea"], "mostrar": "It''s an interesting idea.", "explicacion": "interesting empieza con vocal → an."}'::jsonb, 'ep1-a-an', 'output', false),
  ('banco-ep1-a-an-04', 'banco-ep1', 12, 'decir', '{"es": "Necesito un taxi.", "respuestas": ["i need a taxi"], "mostrar": "I need a taxi.", "explicacion": "taxi empieza con consonante → a."}'::jsonb, 'ep1-a-an', 'output', false),
  ('banco-ep1-a-an-05', 'banco-ep1', 13, 'libre', '{"pregunta": "Say three things you have at home. Use a or an.", "pregunta_es": "Di tres cosas que tienes en casa. Usa a o an.", "ejemplo": "I have a TV, an old sofa and a big table.", "criterio": "a ante sonido de consonante, an ante sonido de vocal.", "explicacion": "a ante sonido de consonante, an ante sonido de vocal."}'::jsonb, 'ep1-a-an', 'output', false),
  ('banco-ep1-a-an-06', 'banco-ep1', 14, 'rapido', '{"frase": "___ egg", "opciones": ["an", "a"], "correcta": 0, "es": "un huevo", "explicacion": "egg → an.", "segundos": 6}'::jsonb, 'ep1-a-an', 'fluidez', false),
  ('banco-ep1-a-an-07', 'banco-ep1', 15, 'rapido', '{"frase": "___ car", "opciones": ["a", "an"], "correcta": 0, "es": "un carro", "explicacion": "car → a.", "segundos": 6}'::jsonb, 'ep1-a-an', 'fluidez', false),
  ('banco-ep1-a-an-08', 'banco-ep1', 16, 'rapido', '{"frase": "___ hour", "opciones": ["an", "a"], "correcta": 0, "es": "una hora", "explicacion": "La h de hour no suena → an.", "segundos": 6}'::jsonb, 'ep1-a-an', 'fluidez', false),
  ('examen-ep1-a-an-01', 'examen-ep1', 4, 'elegir', '{"frase": "She is ___ engineer.", "opciones": ["an", "a", "the"], "correcta": 0, "es": "Ella es ingeniera.", "explicacion": "engineer → an."}'::jsonb, 'ep1-a-an', 'estudio', true),
  ('examen-ep1-a-an-02', 'examen-ep1', 5, 'elegir', '{"frase": "I want ___ umbrella.", "opciones": ["an", "a"], "correcta": 0, "es": "Quiero una sombrilla.", "explicacion": "umbrella → an."}'::jsonb, 'ep1-a-an', 'estudio', true),
  ('examen-ep1-a-an-03', 'examen-ep1', 6, 'escribir', '{"respuestas": ["he is a salesman", "hes a salesman", "he is a seller", "hes a seller"], "mostrar": "He''s a salesman.", "es": "Él es un vendedor.", "explicacion": "Profesión con a."}'::jsonb, 'ep1-a-an', 'estudio', true),
  ('banco-ep1-pronombres-01', 'banco-ep1', 17, 'comprension', '{"modo": "escuchar", "lineas": [{"en": "This is my friend Carla.", "es": "Esta es mi amiga Carla."}, {"en": "Her husband is Mario.", "es": "Su esposo es Mario."}, {"en": "His store is in the center.", "es": "La tienda de él está en el centro."}], "pregunta": "Whose store is in the center?", "pregunta_es": "¿De quién es la tienda del centro?", "opciones": ["Mario''s", "Carla''s", "My store"], "correcta": 0, "explicacion": "His store = la tienda de él (Mario)."}'::jsonb, 'ep1-pronombres', 'input', false),
  ('banco-ep1-pronombres-02', 'banco-ep1', 18, 'comprension', '{"modo": "leer", "lineas": [{"en": "Tom has a dog.", "es": "Tom tiene un perro."}, {"en": "Its name is Max.", "es": "Su nombre es Max."}, {"en": "Tom loves it.", "es": "Tom lo quiere mucho."}], "pregunta": "What is the dog''s name?", "pregunta_es": "¿Cómo se llama el perro?", "opciones": ["Max", "Tom", "Its"], "correcta": 0, "explicacion": "Its name = su nombre (de una cosa o animal)."}'::jsonb, 'ep1-pronombres', 'input', false),
  ('banco-ep1-pronombres-03', 'banco-ep1', 19, 'decir', '{"es": "Su nombre es María. (de ella)", "respuestas": ["her name is maria", "her name is maría"], "mostrar": "Her name is María.", "explicacion": "De ella = her."}'::jsonb, 'ep1-pronombres', 'output', false),
  ('banco-ep1-pronombres-04', 'banco-ep1', 20, 'decir', '{"es": "Él vende zapatos.", "respuestas": ["he sells shoes"], "mostrar": "He sells shoes.", "explicacion": "Él = he (no his)."}'::jsonb, 'ep1-pronombres', 'output', false),
  ('banco-ep1-pronombres-05', 'banco-ep1', 21, 'libre', '{"pregunta": "Talk about a person in your family. Use he/she and his/her.", "pregunta_es": "Habla de una persona de tu familia. Usa he/she y his/her.", "ejemplo": "My wife is Maria. She sells shoes. Her store is online.", "criterio": "he/she para quién hace; his/her para de quién es.", "explicacion": "he/she para quién hace; his/her para de quién es."}'::jsonb, 'ep1-pronombres', 'output', false),
  ('banco-ep1-pronombres-06', 'banco-ep1', 22, 'rapido', '{"frase": "___ name is Laura.", "opciones": ["Her", "She"], "correcta": 0, "es": "Su nombre es Laura.", "explicacion": "De ella = her.", "segundos": 6}'::jsonb, 'ep1-pronombres', 'fluidez', false),
  ('banco-ep1-pronombres-07', 'banco-ep1', 23, 'rapido', '{"frase": "___ is my brother.", "opciones": ["He", "His"], "correcta": 0, "es": "Él es mi hermano.", "explicacion": "Él = he.", "segundos": 6}'::jsonb, 'ep1-pronombres', 'fluidez', false),
  ('banco-ep1-pronombres-08', 'banco-ep1', 24, 'rapido', '{"frase": "My car is old, but ___ works.", "opciones": ["it", "she"], "correcta": 0, "es": "Mi carro es viejo, pero funciona.", "explicacion": "Cosas = it.", "segundos": 6}'::jsonb, 'ep1-pronombres', 'fluidez', false),
  ('examen-ep1-pronombres-01', 'examen-ep1', 7, 'elegir', '{"frase": "That is ___ bag. (de él)", "opciones": ["his", "he", "him"], "correcta": 0, "es": "Ese es el bolso de él.", "explicacion": "De él = his."}'::jsonb, 'ep1-pronombres', 'estudio', true),
  ('examen-ep1-pronombres-02', 'examen-ep1', 8, 'elegir', '{"frase": "Maria and Tom are married. ___ house is big.", "opciones": ["Their", "They", "Her"], "correcta": 0, "es": "María y Tom están casados. Su casa es grande.", "explicacion": "De ellos = their."}'::jsonb, 'ep1-pronombres', 'estudio', true),
  ('examen-ep1-pronombres-03', 'examen-ep1', 9, 'escribir', '{"respuestas": ["her car is red"], "mostrar": "Her car is red.", "es": "Su carro es rojo. (de ella)", "explicacion": "De ella = her."}'::jsonb, 'ep1-pronombres', 'estudio', true),
  ('banco-ep1-profesiones-01', 'banco-ep1', 25, 'comprension', '{"modo": "escuchar", "lineas": [{"en": "My name is Sofia.", "es": "Me llamo Sofía."}, {"en": "I work in a hospital.", "es": "Trabajo en un hospital."}, {"en": "I help sick people.", "es": "Ayudo a personas enfermas."}], "pregunta": "What is Sofia''s job?", "pregunta_es": "¿Cuál es el trabajo de Sofía?", "opciones": ["She is a nurse.", "She is a teacher.", "She is a lawyer."], "correcta": 0, "explicacion": "Trabaja en un hospital y ayuda a enfermos → nurse."}'::jsonb, 'ep1-profesiones', 'input', false),
  ('banco-ep1-profesiones-02', 'banco-ep1', 26, 'comprension', '{"modo": "leer", "lineas": [{"en": "Andrés is a taxi driver.", "es": "Andrés es taxista."}, {"en": "He drives all day.", "es": "Maneja todo el día."}, {"en": "His wife is a cook in a restaurant.", "es": "Su esposa es cocinera en un restaurante."}], "pregunta": "What does Andrés''s wife do?", "pregunta_es": "¿A qué se dedica la esposa de Andrés?", "opciones": ["She is a cook.", "She is a driver.", "She is a nurse."], "correcta": 0, "explicacion": "cook = cocinero(a)."}'::jsonb, 'ep1-profesiones', 'input', false),
  ('banco-ep1-profesiones-03', 'banco-ep1', 27, 'decir', '{"es": "Soy vendedor.", "respuestas": ["i am a salesman", "im a salesman", "i am a seller", "im a seller"], "mostrar": "I''m a salesman.", "explicacion": "Profesión con a."}'::jsonb, 'ep1-profesiones', 'output', false),
  ('banco-ep1-profesiones-04', 'banco-ep1', 28, 'decir', '{"es": "Mi hermano es abogado.", "respuestas": ["my brother is a lawyer"], "mostrar": "My brother is a lawyer.", "explicacion": "lawyer = abogado."}'::jsonb, 'ep1-profesiones', 'output', false),
  ('banco-ep1-profesiones-05', 'banco-ep1', 29, 'libre', '{"pregunta": "What do you do? Describe your job in two sentences.", "pregunta_es": "¿A qué te dedicas? Describe tu trabajo en dos frases.", "ejemplo": "I''m a businessman. I sell shoes on social media.", "criterio": "Usa I''m a/an + profesión.", "explicacion": "Usa I''m a/an + profesión."}'::jsonb, 'ep1-profesiones', 'output', false),
  ('banco-ep1-profesiones-06', 'banco-ep1', 30, 'rapido', '{"frase": "A ___ works in a school.", "opciones": ["teacher", "nurse"], "correcta": 0, "es": "Un profesor trabaja en un colegio.", "explicacion": "teacher = profesor.", "segundos": 6}'::jsonb, 'ep1-profesiones', 'fluidez', false),
  ('banco-ep1-profesiones-07', 'banco-ep1', 31, 'rapido', '{"frase": "A ___ drives a taxi.", "opciones": ["driver", "cook"], "correcta": 0, "es": "Un conductor maneja un taxi.", "explicacion": "driver = conductor.", "segundos": 6}'::jsonb, 'ep1-profesiones', 'fluidez', false),
  ('banco-ep1-profesiones-08', 'banco-ep1', 32, 'rapido', '{"frase": "I''m ___ engineer.", "opciones": ["an", "a"], "correcta": 0, "es": "Soy ingeniero.", "explicacion": "engineer → an.", "segundos": 6}'::jsonb, 'ep1-profesiones', 'fluidez', false),
  ('examen-ep1-profesiones-01', 'examen-ep1', 10, 'emparejar', '{"pares": [["doctor", "médico"], ["cook", "cocinero"], ["lawyer", "abogado"], ["teacher", "profesor"]], "es": "", "explicacion": "Profesiones básicas."}'::jsonb, 'ep1-profesiones', 'estudio', true),
  ('examen-ep1-profesiones-02', 'examen-ep1', 11, 'elegir', '{"frase": "What do you do? — I''m ___ nurse.", "opciones": ["a", "an", "—"], "correcta": 0, "es": "¿A qué te dedicas? — Soy enfermera.", "explicacion": "En inglés la profesión lleva a/an."}'::jsonb, 'ep1-profesiones', 'estudio', true),
  ('examen-ep1-profesiones-03', 'examen-ep1', 12, 'escribir', '{"respuestas": ["she is a teacher", "shes a teacher"], "mostrar": "She''s a teacher.", "es": "Ella es profesora.", "explicacion": "Profesión con a."}'::jsonb, 'ep1-profesiones', 'estudio', true),
  ('banco-ep1-clima-01', 'banco-ep1', 33, 'comprension', '{"modo": "escuchar", "lineas": [{"en": "Good morning!", "es": "¡Buenos días!"}, {"en": "Today it''s cloudy and cold in Bogotá.", "es": "Hoy está nublado y frío en Bogotá."}, {"en": "Take a jacket.", "es": "Lleva una chaqueta."}], "pregunta": "How is the weather in Bogotá?", "pregunta_es": "¿Cómo está el clima en Bogotá?", "opciones": ["Cloudy and cold.", "Sunny and hot.", "Rainy and hot."], "correcta": 0, "explicacion": "cloudy = nublado, cold = frío."}'::jsonb, 'ep1-clima', 'input', false),
  ('banco-ep1-clima-02', 'banco-ep1', 34, 'comprension', '{"modo": "leer", "lineas": [{"en": "In Cúcuta it''s very hot.", "es": "En Cúcuta hace mucho calor."}, {"en": "It''s sunny almost every day.", "es": "Está soleado casi todos los días."}, {"en": "In the afternoon it''s sometimes rainy.", "es": "En la tarde a veces llueve."}], "pregunta": "Is it cold in Cúcuta?", "pregunta_es": "¿Hace frío en Cúcuta?", "opciones": ["No, it''s very hot.", "Yes, it''s cold.", "Yes, it''s cloudy."], "correcta": 0, "explicacion": "very hot = mucho calor."}'::jsonb, 'ep1-clima', 'input', false),
  ('banco-ep1-clima-03', 'banco-ep1', 35, 'decir', '{"es": "Hoy está lloviendo... está lluvioso.", "respuestas": ["it is rainy", "its rainy", "it is rainy today", "its rainy today"], "mostrar": "It''s rainy today.", "explicacion": "Clima con It''s."}'::jsonb, 'ep1-clima', 'output', false),
  ('banco-ep1-clima-04', 'banco-ep1', 36, 'decir', '{"es": "Hace frío.", "respuestas": ["it is cold", "its cold"], "mostrar": "It''s cold.", "explicacion": "Hacer frío = It''s cold."}'::jsonb, 'ep1-clima', 'output', false),
  ('banco-ep1-clima-05', 'banco-ep1', 37, 'libre', '{"pregunta": "How is the weather today in your city?", "pregunta_es": "¿Cómo está el clima hoy en tu ciudad?", "ejemplo": "Today it''s hot and sunny in Cúcuta.", "criterio": "Usa It''s + palabra del clima.", "explicacion": "Usa It''s + palabra del clima."}'::jsonb, 'ep1-clima', 'output', false),
  ('banco-ep1-clima-06', 'banco-ep1', 38, 'rapido', '{"frase": "It''s ___. Take an umbrella.", "opciones": ["rainy", "sunny"], "correcta": 0, "es": "Está lluvioso. Lleva sombrilla.", "explicacion": "rainy = lluvioso.", "segundos": 6}'::jsonb, 'ep1-clima', 'fluidez', false),
  ('banco-ep1-clima-07', 'banco-ep1', 39, 'rapido', '{"frase": "Hace calor = It''s ___.", "opciones": ["hot", "cold"], "correcta": 0, "es": "", "explicacion": "hot = calor.", "segundos": 6}'::jsonb, 'ep1-clima', 'fluidez', false),
  ('banco-ep1-clima-08', 'banco-ep1', 40, 'rapido', '{"frase": "Nublado = ___", "opciones": ["cloudy", "sunny"], "correcta": 0, "es": "", "explicacion": "cloudy = nublado.", "segundos": 6}'::jsonb, 'ep1-clima', 'fluidez', false),
  ('examen-ep1-clima-01', 'examen-ep1', 13, 'elegir', '{"frase": "What''s the weather like? — ___ sunny.", "opciones": ["It''s", "Is", "It"], "correcta": 0, "es": "¿Cómo está el clima? — Está soleado.", "explicacion": "It''s + clima."}'::jsonb, 'ep1-clima', 'estudio', true),
  ('examen-ep1-clima-02', 'examen-ep1', 14, 'escuchar', '{"opciones": ["It''s windy and cold.", "It''s sunny and cold.", "It''s windy and hot."], "correcta": 0, "audio": "It''s windy and cold.", "es": "Hace viento y frío.", "explicacion": "windy = con viento."}'::jsonb, 'ep1-clima', 'input', true),
  ('examen-ep1-clima-03', 'examen-ep1', 15, 'escribir', '{"respuestas": ["it is sunny today", "its sunny today"], "mostrar": "It''s sunny today.", "es": "Está soleado hoy.", "explicacion": "It''s sunny."}'::jsonb, 'ep1-clima', 'estudio', true),
  ('banco-ep1-adjetivos-01', 'banco-ep1', 41, 'comprension', '{"modo": "escuchar", "lineas": [{"en": "I have a new phone.", "es": "Tengo un teléfono nuevo."}, {"en": "It''s small and black.", "es": "Es pequeño y negro."}, {"en": "It''s very fast.", "es": "Es muy rápido."}], "pregunta": "What color is the phone?", "pregunta_es": "¿De qué color es el teléfono?", "opciones": ["Black", "White", "Small"], "correcta": 0, "explicacion": "small and black = pequeño y negro."}'::jsonb, 'ep1-adjetivos', 'input', false),
  ('banco-ep1-adjetivos-02', 'banco-ep1', 42, 'comprension', '{"modo": "leer", "lineas": [{"en": "Laura has a beautiful house.", "es": "Laura tiene una casa bonita."}, {"en": "It''s big and white.", "es": "Es grande y blanca."}, {"en": "It has a green door.", "es": "Tiene una puerta verde."}], "pregunta": "What color is the door?", "pregunta_es": "¿De qué color es la puerta?", "opciones": ["Green", "White", "Big"], "correcta": 0, "explicacion": "a green door: el color va antes."}'::jsonb, 'ep1-adjetivos', 'input', false),
