  ('banco-ep1-comparativos-02', 'banco-ep1', 58, 'comprension', '{"modo": "leer", "lineas": [{"en": "Bogotá is colder than Cúcuta.", "es": "Bogotá es más fría que Cúcuta."}, {"en": "Cúcuta is hotter than Bogotá.", "es": "Cúcuta es más caliente que Bogotá."}, {"en": "Bogotá is the biggest city in Colombia.", "es": "Bogotá es la ciudad más grande de Colombia."}], "pregunta": "Which city is the biggest?", "pregunta_es": "¿Cuál es la ciudad más grande?", "opciones": ["Bogotá", "Cúcuta", "Both"], "correcta": 0, "explicacion": "the biggest = la más grande."}'::jsonb, 'ep1-comparativos', 'input', false),
