  ('banco-ep1-comparativos-05', 'banco-ep1', 61, 'libre', '{"pregunta": "Compare two cities or two people you know.", "pregunta_es": "Compara dos ciudades o dos personas que conozcas.", "ejemplo": "Cúcuta is hotter than Bogotá, but Bogotá is bigger.", "criterio": "Usa -er than / more … than / the -est.", "explicacion": "Usa -er than / more … than / the -est."}'::jsonb, 'ep1-comparativos', 'output', false),
