  ('banco-ep2-presente-s-04', 'banco-ep2', 4, 'decir', '{"es": "Yo estudio inglés todos los días.", "respuestas": ["i study english every day"], "mostrar": "I study English every day.", "explicacion": "Con I no hay -s."}'::jsonb, 'ep2-presente-s', 'output', false),
  ('banco-ep2-presente-s-05', 'banco-ep2', 5, 'libre', '{"pregunta": "Describe the routine of a person in your family. Use he or she.", "pregunta_es": "Describe la rutina de una persona de tu familia. Usa he o she.", "ejemplo": "My wife wakes up at six. She makes coffee and she sells shoes online.", "criterio": "Con he/she el verbo lleva -s.", "explicacion": "Con he/she el verbo lleva -s."}'::jsonb, 'ep2-presente-s', 'output', false),
