  ('banco-ep2-do-does-02', 'banco-ep2', 10, 'comprension', '{"modo": "leer", "lineas": [{"en": "Tom doesn''t work on Sundays.", "es": "Tom no trabaja los domingos."}, {"en": "He doesn''t get up early.", "es": "No se levanta temprano."}, {"en": "He plays soccer with his friends.", "es": "Juega fútbol con sus amigos."}], "pregunta": "Does Tom work on Sundays?", "pregunta_es": "¿Tom trabaja los domingos?", "opciones": ["No, he doesn''t.", "Yes, he does.", "No, he don''t."], "correcta": 0, "explicacion": "Respuesta corta: No, he doesn''t."}'::jsonb, 'ep2-do-does', 'input', false),
