  ('banco-ep2-do-does-04', 'banco-ep2', 12, 'decir', '{"es": "Él no tiene carro.", "respuestas": ["he does not have a car", "he doesnt have a car"], "mostrar": "He doesn''t have a car.", "explicacion": "doesn''t + verbo base (have, no has)."}'::jsonb, 'ep2-do-does', 'output', false),
  ('banco-ep2-do-does-05', 'banco-ep2', 13, 'libre', '{"pregunta": "Ask three questions to a new friend with do or does.", "pregunta_es": "Hazle tres preguntas a un amigo nuevo con do o does.", "ejemplo": "Do you work? Where do you live? Does your family live here?", "criterio": "Do con you; does con he/she; verbo sin -s.", "explicacion": "Do con you; does con he/she; verbo sin -s."}'::jsonb, 'ep2-do-does', 'output', false),
