  ('banco-ep2-rutinas-02', 'banco-ep2', 18, 'comprension', '{"modo": "leer", "lineas": [{"en": "Maria gets home at six.", "es": "María llega a casa a las seis."}, {"en": "She cooks dinner and helps her daughter with homework.", "es": "Cocina la cena y ayuda a su hija con la tarea."}, {"en": "She goes to bed at ten.", "es": "Se acuesta a las diez."}], "pregunta": "What time does she go to bed?", "pregunta_es": "¿A qué hora se acuesta?", "opciones": ["At ten.", "At six.", "At seven."], "correcta": 0, "explicacion": "go to bed = acostarse."}'::jsonb, 'ep2-rutinas', 'input', false),
