  ('examen-ep2-rutinas-03', 'examen-ep2', 9, 'escribir', '{"respuestas": ["i have lunch at twelve", "i have lunch at 12"], "mostrar": "I have lunch at twelve.", "es": "Almuerzo a las doce.", "explicacion": "have lunch."}'::jsonb, 'ep2-rutinas', 'estudio', true),
  ('banco-ep2-plurales-01', 'banco-ep2', 25, 'comprension', '{"modo": "escuchar", "lineas": [{"en": "In my store there are two men and three women.", "es": "En mi tienda hay dos hombres y tres mujeres."}, {"en": "The children are at school.", "es": "Los niños están en el colegio."}], "pregunta": "How many women are in the store?", "pregunta_es": "¿Cuántas mujeres hay en la tienda?", "opciones": ["Three", "Two", "Five"], "correcta": 0, "explicacion": "women = mujeres (plural de woman)."}'::jsonb, 'ep2-plurales', 'input', false),
  ('banco-ep2-plurales-02', 'banco-ep2', 26, 'comprension', '{"modo": "leer", "lineas": [{"en": "I sell shoes, bags and watches.", "es": "Vendo zapatos, bolsos y relojes."}, {"en": "Many people buy two pairs of shoes.", "es": "Mucha gente compra dos pares de zapatos."}], "pregunta": "What does he sell?", "pregunta_es": "¿Qué vende?", "opciones": ["Shoes, bags and watches", "Only shoes", "Phones"], "correcta": 0, "explicacion": "watch → watches (-es)."}'::jsonb, 'ep2-plurales', 'input', false),
  ('banco-ep2-plurales-03', 'banco-ep2', 27, 'decir', '{"es": "Tengo dos hijos.", "respuestas": ["i have two children", "i have 2 children", "i have two sons"], "mostrar": "I have two children.", "explicacion": "child → children."}'::jsonb, 'ep2-plurales', 'output', false),
  ('banco-ep2-plurales-04', 'banco-ep2', 28, 'decir', '{"es": "Hay muchas personas aquí.", "respuestas": ["there are many people here"], "mostrar": "There are many people here.", "explicacion": "person → people."}'::jsonb, 'ep2-plurales', 'output', false),
  ('banco-ep2-plurales-05', 'banco-ep2', 29, 'libre', '{"pregunta": "Say what you sell or what you have at home. Use plurals.", "pregunta_es": "Di qué vendes o qué tienes en casa. Usa plurales.", "ejemplo": "I sell shoes and bags. I have two phones and three watches.", "criterio": "-s, -es y plurales irregulares.", "explicacion": "-s, -es y plurales irregulares."}'::jsonb, 'ep2-plurales', 'output', false),
  ('banco-ep2-plurales-06', 'banco-ep2', 30, 'rapido', '{"frase": "one man, two ___", "opciones": ["men", "mans"], "correcta": 0, "es": "", "explicacion": "man → men.", "segundos": 6}'::jsonb, 'ep2-plurales', 'fluidez', false),
  ('banco-ep2-plurales-07', 'banco-ep2', 31, 'rapido', '{"frase": "one box, two ___", "opciones": ["boxes", "boxs"], "correcta": 0, "es": "", "explicacion": "-x → -es.", "segundos": 6}'::jsonb, 'ep2-plurales', 'fluidez', false),
  ('banco-ep2-plurales-08', 'banco-ep2', 32, 'rapido', '{"frase": "one foot, two ___", "opciones": ["feet", "foots"], "correcta": 0, "es": "", "explicacion": "foot → feet.", "segundos": 6}'::jsonb, 'ep2-plurales', 'fluidez', false),
  ('examen-ep2-plurales-01', 'examen-ep2', 10, 'elegir', '{"frase": "One child, three ___.", "opciones": ["children", "childs", "childrens"], "correcta": 0, "es": "Un niño, tres niños.", "explicacion": "child → children."}'::jsonb, 'ep2-plurales', 'estudio', true),
  ('examen-ep2-plurales-02', 'examen-ep2', 11, 'elegir', '{"frase": "Those ___ are expensive.", "opciones": ["watches", "watchs", "watch"], "correcta": 0, "es": "Esos relojes son caros.", "explicacion": "-ch → -es."}'::jsonb, 'ep2-plurales', 'estudio', true),
  ('examen-ep2-plurales-03', 'examen-ep2', 12, 'escribir', '{"respuestas": ["two women", "2 women"], "mostrar": "two women", "es": "Dos mujeres", "explicacion": "woman → women."}'::jsonb, 'ep2-plurales', 'estudio', true),
  ('banco-ep2-this-that-01', 'banco-ep2', 33, 'elegir', '{"frase": "___ is my phone. (aquí, en mi mano)", "opciones": ["This", "That", "These"], "correcta": 0, "es": "Este es mi teléfono.", "explicacion": "This = este (cerca, uno)."}'::jsonb, 'ep2-this-that', 'estudio', false),
  ('banco-ep2-this-that-02', 'banco-ep2', 34, 'elegir', '{"frase": "___ shoes over there are cheap.", "opciones": ["Those", "These", "That"], "correcta": 0, "es": "Esos zapatos de allá son baratos.", "explicacion": "Those = esos (lejos, varios)."}'::jsonb, 'ep2-this-that', 'estudio', false),
  ('banco-ep2-this-that-03', 'banco-ep2', 35, 'emparejar', '{"pares": [["this", "este (cerca)"], ["that", "ese (lejos)"], ["these", "estos (cerca)"], ["those", "esos (lejos)"]], "es": "", "explicacion": "Cerca/lejos y uno/varios."}'::jsonb, 'ep2-this-that', 'estudio', false),
  ('banco-ep2-this-that-04', 'banco-ep2', 36, 'escribir', '{"respuestas": ["these shoes are new"], "mostrar": "These shoes are new.", "es": "Estos zapatos son nuevos.", "explicacion": "These + plural."}'::jsonb, 'ep2-this-that', 'estudio', false),
  ('banco-ep2-this-that-05', 'banco-ep2', 37, 'comprension', '{"modo": "escuchar", "lineas": [{"en": "How much are these shoes?", "es": "¿Cuánto cuestan estos zapatos?"}, {"en": "These are forty thousand pesos.", "es": "Estos cuestan cuarenta mil pesos."}, {"en": "And those?", "es": "¿Y esos?"}, {"en": "Those are fifty thousand.", "es": "Esos cuestan cincuenta mil."}], "pregunta": "How much are those shoes?", "pregunta_es": "¿Cuánto cuestan esos zapatos?", "opciones": ["50,000 pesos", "40,000 pesos", "15,000 pesos"], "correcta": 0, "explicacion": "those = esos (los de allá)."}'::jsonb, 'ep2-this-that', 'input', false),
  ('banco-ep2-this-that-06', 'banco-ep2', 38, 'comprension', '{"modo": "leer", "lineas": [{"en": "This is my store.", "es": "Esta es mi tienda."}, {"en": "That building over there is the bank.", "es": "Ese edificio de allá es el banco."}, {"en": "These people are my clients.", "es": "Estas personas son mis clientes."}], "pregunta": "What is that building?", "pregunta_es": "¿Qué es ese edificio?", "opciones": ["The bank", "The store", "The clients"], "correcta": 0, "explicacion": "that = ese (lejos)."}'::jsonb, 'ep2-this-that', 'input', false),
  ('banco-ep2-this-that-07', 'banco-ep2', 39, 'decir', '{"es": "Esta es mi esposa.", "respuestas": ["this is my wife"], "mostrar": "This is my wife.", "explicacion": "Para presentar: This is…"}'::jsonb, 'ep2-this-that', 'output', false),
  ('banco-ep2-this-that-08', 'banco-ep2', 40, 'decir', '{"es": "¿Cuánto cuestan esos?", "respuestas": ["how much are those"], "mostrar": "How much are those?", "explicacion": "Those = esos (plural, lejos)."}'::jsonb, 'ep2-this-that', 'output', false),
  ('banco-ep2-this-that-09', 'banco-ep2', 41, 'libre', '{"pregunta": "You are in a store. Ask about two products: one near you and one far.", "pregunta_es": "Estás en una tienda. Pregunta por dos productos: uno cerca y otro lejos.", "ejemplo": "How much is this bag? And how much are those shoes?", "criterio": "this/these cerca; that/those lejos.", "explicacion": "this/these cerca; that/those lejos."}'::jsonb, 'ep2-this-that', 'output', false),
  ('banco-ep2-this-that-10', 'banco-ep2', 42, 'rapido', '{"frase": "___ shoes (cerca)", "opciones": ["these", "this"], "correcta": 0, "es": "estos zapatos", "explicacion": "plural cerca → these.", "segundos": 6}'::jsonb, 'ep2-this-that', 'fluidez', false),
  ('banco-ep2-this-that-11', 'banco-ep2', 43, 'rapido', '{"frase": "___ car (lejos)", "opciones": ["that", "those"], "correcta": 0, "es": "ese carro", "explicacion": "singular lejos → that.", "segundos": 6}'::jsonb, 'ep2-this-that', 'fluidez', false),
  ('banco-ep2-this-that-12', 'banco-ep2', 44, 'rapido', '{"frase": "___ people (lejos)", "opciones": ["those", "that"], "correcta": 0, "es": "esas personas", "explicacion": "plural lejos → those.", "segundos": 6}'::jsonb, 'ep2-this-that', 'fluidez', false),
  ('examen-ep2-this-that-01', 'examen-ep2', 13, 'elegir', '{"frase": "Is ___ your bag over there?", "opciones": ["that", "this", "these"], "correcta": 0, "es": "¿Ese de allá es tu bolso?", "explicacion": "Lejos y uno → that."}'::jsonb, 'ep2-this-that', 'estudio', true),
  ('examen-ep2-this-that-02', 'examen-ep2', 14, 'elegir', '{"frase": "___ are my children. (aquí conmigo)", "opciones": ["These", "Those", "This"], "correcta": 0, "es": "Estos son mis hijos.", "explicacion": "Cerca y varios → these."}'::jsonb, 'ep2-this-that', 'estudio', true),
  ('examen-ep2-this-that-03', 'examen-ep2', 15, 'escribir', '{"respuestas": ["that is my car", "thats my car"], "mostrar": "That''s my car.", "es": "Ese es mi carro. (lejos)", "explicacion": "that = ese."}'::jsonb, 'ep2-this-that', 'estudio', true),
  ('banco-ep2-the-01', 'banco-ep2', 45, 'elegir', '{"frase": "Can you close ___ door, please?", "opciones": ["the", "a", "—"], "correcta": 0, "es": "¿Puedes cerrar la puerta, por favor?", "explicacion": "Una puerta específica que ambos conocen → the."}'::jsonb, 'ep2-the', 'estudio', false),
  ('banco-ep2-the-02', 'banco-ep2', 46, 'elegir', '{"frase": "I like ___ coffee.", "opciones": ["—", "the", "a"], "correcta": 0, "es": "Me gusta el café.", "explicacion": "Hablando en general no se usa the: I like coffee."}'::jsonb, 'ep2-the', 'estudio', false),
  ('banco-ep2-the-03', 'banco-ep2', 47, 'elegir', '{"frase": "She plays ___ guitar.", "opciones": ["the", "a", "—"], "correcta": 0, "es": "Ella toca la guitarra.", "explicacion": "Instrumentos musicales llevan the."}'::jsonb, 'ep2-the', 'estudio', false),
  ('banco-ep2-the-04', 'banco-ep2', 48, 'escribir', '{"respuestas": ["the bank is closed"], "mostrar": "The bank is closed.", "es": "El banco está cerrado.", "explicacion": "Un banco específico → the."}'::jsonb, 'ep2-the', 'estudio', false),
  ('banco-ep2-the-05', 'banco-ep2', 49, 'comprension', '{"modo": "escuchar", "lineas": [{"en": "I have a dog and a cat.", "es": "Tengo un perro y un gato."}, {"en": "The dog is big.", "es": "El perro es grande."}, {"en": "The cat is small and white.", "es": "El gato es pequeño y blanco."}], "pregunta": "How is the cat?", "pregunta_es": "¿Cómo es el gato?", "opciones": ["Small and white", "Big", "Black"], "correcta": 0, "explicacion": "Primera vez: a cat; después: the cat."}'::jsonb, 'ep2-the', 'input', false),
  ('banco-ep2-the-06', 'banco-ep2', 50, 'comprension', '{"modo": "leer", "lineas": [{"en": "People love music.", "es": "A la gente le encanta la música."}, {"en": "The music in this café is very good.", "es": "La música de este café es muy buena."}], "pregunta": "Which sentence talks about music in general?", "pregunta_es": "¿Qué frase habla de la música en general?", "opciones": ["People love music.", "The music in this café is very good."], "correcta": 0, "explicacion": "En general, sin the: People love music."}'::jsonb, 'ep2-the', 'input', false),
  ('banco-ep2-the-07', 'banco-ep2', 51, 'decir', '{"es": "Me encanta el chocolate.", "respuestas": ["i love chocolate"], "mostrar": "I love chocolate.", "explicacion": "En general, sin the."}'::jsonb, 'ep2-the', 'output', false),
  ('banco-ep2-the-08', 'banco-ep2', 52, 'decir', '{"es": "La tienda está en el centro.", "respuestas": ["the store is in the center", "the shop is in the center", "the store is downtown"], "mostrar": "The store is in the center.", "explicacion": "Tienda específica → the."}'::jsonb, 'ep2-the', 'output', false),
  ('banco-ep2-the-09', 'banco-ep2', 53, 'libre', '{"pregunta": "Say two things you like in general and one specific thing in your house.", "pregunta_es": "Di dos cosas que te gustan en general y una cosa específica de tu casa.", "ejemplo": "I like music and coffee. The sofa in my house is very comfortable.", "criterio": "Sin the en general; con the lo específico.", "explicacion": "Sin the en general; con the lo específico."}'::jsonb, 'ep2-the', 'output', false),
  ('banco-ep2-the-10', 'banco-ep2', 54, 'rapido', '{"frase": "I love ___ music.", "opciones": ["—", "the"], "correcta": 0, "es": "Me encanta la música.", "explicacion": "General → sin the.", "segundos": 6}'::jsonb, 'ep2-the', 'fluidez', false),
  ('banco-ep2-the-11', 'banco-ep2', 55, 'rapido', '{"frase": "Open ___ window, please.", "opciones": ["the", "—"], "correcta": 0, "es": "Abre la ventana.", "explicacion": "Específica → the.", "segundos": 6}'::jsonb, 'ep2-the', 'fluidez', false),
  ('banco-ep2-the-12', 'banco-ep2', 56, 'rapido', '{"frase": "I play ___ piano.", "opciones": ["the", "—"], "correcta": 0, "es": "Toco el piano.", "explicacion": "Instrumentos → the.", "segundos": 6}'::jsonb, 'ep2-the', 'fluidez', false),
  ('examen-ep2-the-01', 'examen-ep2', 16, 'elegir', '{"frase": "___ sun is very hot today.", "opciones": ["The", "A", "—"], "correcta": 0, "es": "El sol está muy fuerte hoy.", "explicacion": "Algo único → the."}'::jsonb, 'ep2-the', 'estudio', true),
  ('examen-ep2-the-02', 'examen-ep2', 17, 'elegir', '{"frase": "I don''t like ___ rice.", "opciones": ["—", "the", "a"], "correcta": 0, "es": "No me gusta el arroz.", "explicacion": "En general → sin the."}'::jsonb, 'ep2-the', 'estudio', true),
  ('examen-ep2-the-03', 'examen-ep2', 18, 'escribir', '{"respuestas": ["the door is open"], "mostrar": "The door is open.", "es": "La puerta está abierta.", "explicacion": "Específica → the."}'::jsonb, 'ep2-the', 'estudio', true),
  ('banco-ep2-numeros-01', 'banco-ep2', 57, 'emparejar', '{"pares": [["13", "thirteen"], ["30", "thirty"], ["15", "fifteen"], ["50", "fifty"]], "es": "", "explicacion": "-teen (13–19) suena largo al final; -ty (20, 30…) suena corto al inicio."}'::jsonb, 'ep2-numeros', 'estudio', false),
  ('banco-ep2-numeros-02', 'banco-ep2', 58, 'elegir', '{"frase": "¿Cómo se escribe 45?", "opciones": ["forty-five", "fourty-five", "fourteen-five"], "correcta": 0, "es": "cuarenta y cinco", "explicacion": "40 = forty (sin u)."}'::jsonb, 'ep2-numeros', 'estudio', false),
  ('banco-ep2-numeros-03', 'banco-ep2', 59, 'escribir', '{"respuestas": ["i am thirty eight years old", "im thirty eight years old", "i am thirty-eight years old", "im thirty-eight years old", "i am 38 years old", "im 38 years old", "i am thirty eight", "im thirty eight", "i am 38", "im 38"], "mostrar": "I''m thirty-eight years old.", "es": "Tengo treinta y ocho años.", "explicacion": "Edad con to be: I am … years old."}'::jsonb, 'ep2-numeros', 'estudio', false),
  ('banco-ep2-numeros-04', 'banco-ep2', 60, 'elegir', '{"frase": "100 =", "opciones": ["one hundred", "one thousand", "ten"], "correcta": 0, "es": "cien", "explicacion": "hundred = 100; thousand = 1.000."}'::jsonb, 'ep2-numeros', 'estudio', false),
  ('banco-ep2-numeros-05', 'banco-ep2', 61, 'comprension', '{"modo": "escuchar", "lineas": [{"en": "The shoes are sixty thousand pesos.", "es": "Los zapatos cuestan sesenta mil pesos."}, {"en": "The bag is twenty-five thousand.", "es": "El bolso cuesta veinticinco mil."}], "pregunta": "How much is the bag?", "pregunta_es": "¿Cuánto cuesta el bolso?", "opciones": ["25,000", "60,000", "16,000"], "correcta": 0, "explicacion": "twenty-five = 25."}'::jsonb, 'ep2-numeros', 'input', false),
  ('banco-ep2-numeros-06', 'banco-ep2', 62, 'comprension', '{"modo": "leer", "lineas": [{"en": "My phone number is three one five, two four eight, nine zero seven seven.", "es": "Mi número es 315 248 9077."}], "pregunta": "What is the number?", "pregunta_es": "¿Cuál es el número?", "opciones": ["315 248 9077", "315 284 9077", "350 248 9077"], "correcta": 0, "explicacion": "Los teléfonos se dicen número por número; 0 = zero."}'::jsonb, 'ep2-numeros', 'input', false),
  ('banco-ep2-numeros-07', 'banco-ep2', 63, 'decir', '{"es": "Cuesta cincuenta mil pesos.", "respuestas": ["it costs fifty thousand pesos", "its fifty thousand pesos", "it is fifty thousand pesos", "it costs 50000 pesos"], "mostrar": "It costs fifty thousand pesos.", "explicacion": "fifty = 50; thousand = mil."}'::jsonb, 'ep2-numeros', 'output', false),
  ('banco-ep2-numeros-08', 'banco-ep2', 64, 'decir', '{"es": "Tengo dos hijos y una tienda.", "respuestas": ["i have two children and one store", "i have two children and a store", "i have two kids and a store", "i have 2 children and a store"], "mostrar": "I have two children and a store.", "explicacion": "Números con sustantivos en plural."}'::jsonb, 'ep2-numeros', 'output', false),
  ('banco-ep2-numeros-09', 'banco-ep2', 65, 'libre', '{"pregunta": "Say your age, how many people live in your house and a price you know.", "pregunta_es": "Di tu edad, cuántas personas viven en tu casa y un precio que conozcas.", "ejemplo": "I''m 40 years old. Four people live in my house. A coffee is three thousand pesos.", "criterio": "Números bien dichos; edad con I''m … years old.", "explicacion": "Números bien dichos; edad con I''m … years old."}'::jsonb, 'ep2-numeros', 'output', false),
  ('banco-ep2-numeros-10', 'banco-ep2', 66, 'rapido', '{"frase": "fifteen =", "opciones": ["15", "50"], "correcta": 0, "es": "", "explicacion": "-teen = 13–19.", "segundos": 6}'::jsonb, 'ep2-numeros', 'fluidez', false),
  ('banco-ep2-numeros-11', 'banco-ep2', 67, 'rapido', '{"frase": "fifty =", "opciones": ["50", "15"], "correcta": 0, "es": "", "explicacion": "-ty = decenas.", "segundos": 6}'::jsonb, 'ep2-numeros', 'fluidez', false),
