  ('examen-ep2-numeros-01', 'examen-ep2', 19, 'escuchar', '{"opciones": ["seventeen", "seventy", "seven"], "correcta": 0, "audio": "seventeen", "es": "diecisiete", "explicacion": "seventeen = 17 (acento al final)."}'::jsonb, 'ep2-numeros', 'input', true),
  ('examen-ep2-numeros-02', 'examen-ep2', 20, 'elegir', '{"frase": "How old are you? — I''m ___.", "opciones": ["forty", "fourty", "fourteen years"], "correcta": 0, "es": "¿Cuántos años tienes? — Tengo cuarenta.", "explicacion": "40 = forty."}'::jsonb, 'ep2-numeros', 'estudio', true),
  ('examen-ep2-numeros-03', 'examen-ep2', 21, 'escribir', '{"respuestas": ["twelve", "12"], "mostrar": "twelve", "es": "Doce", "explicacion": "12 = twelve."}'::jsonb, 'ep2-numeros', 'estudio', true),
  ('banco-ep2-hora-01', 'banco-ep2', 69, 'elegir', '{"frase": "8:30 =", "opciones": ["half past eight", "half past nine", "eight and half"], "correcta": 0, "es": "ocho y media", "explicacion": "half past = y media."}'::jsonb, 'ep2-hora', 'estudio', false),
  ('banco-ep2-hora-02', 'banco-ep2', 70, 'elegir', '{"frase": "7:15 =", "opciones": ["a quarter past seven", "a quarter to seven", "seven quarter"], "correcta": 0, "es": "siete y cuarto", "explicacion": "a quarter past = y cuarto."}'::jsonb, 'ep2-hora', 'estudio', false),
