  ('banco-ep2-hora-05', 'banco-ep2', 73, 'comprension', '{"modo": "escuchar", "lineas": [{"en": "Excuse me, what time is it?", "es": "Disculpe, ¿qué hora es?"}, {"en": "It''s a quarter to three.", "es": "Son las tres menos cuarto."}, {"en": "Thank you!", "es": "¡Gracias!"}], "pregunta": "What time is it?", "pregunta_es": "¿Qué hora es?", "opciones": ["2:45", "3:15", "3:45"], "correcta": 0, "explicacion": "a quarter to three = 2:45."}'::jsonb, 'ep2-hora', 'input', false),
  ('banco-ep2-hora-06', 'banco-ep2', 74, 'comprension', '{"modo": "leer", "lineas": [{"en": "The store opens at nine o''clock.", "es": "La tienda abre a las nueve."}, {"en": "It closes at half past six.", "es": "Cierra a las seis y media."}], "pregunta": "When does the store close?", "pregunta_es": "¿Cuándo cierra la tienda?", "opciones": ["6:30", "9:00", "6:00"], "correcta": 0, "explicacion": "half past six = 6:30."}'::jsonb, 'ep2-hora', 'input', false),
  ('banco-ep2-hora-07', 'banco-ep2', 75, 'decir', '{"es": "Son las diez en punto.", "respuestas": ["it is ten oclock", "its ten oclock", "it is ten", "its ten"], "mostrar": "It''s ten o''clock.", "explicacion": "en punto = o''clock."}'::jsonb, 'ep2-hora', 'output', false),
  ('banco-ep2-hora-08', 'banco-ep2', 76, 'decir', '{"es": "Abro mi tienda a las ocho y media.", "respuestas": ["i open my store at half past eight", "i open my shop at half past eight", "i open my store at eight thirty", "i open my shop at eight thirty"], "mostrar": "I open my store at half past eight.", "explicacion": "y media = half past."}'::jsonb, 'ep2-hora', 'output', false),
  ('banco-ep2-hora-09', 'banco-ep2', 77, 'libre', '{"pregunta": "What time do you wake up, have lunch and go to bed?", "pregunta_es": "¿A qué hora te levantas, almuerzas y te acuestas?", "ejemplo": "I wake up at six o''clock, I have lunch at half past twelve and I go to bed at eleven.", "criterio": "Horas con at: at six o''clock.", "explicacion": "Horas con at: at six o''clock."}'::jsonb, 'ep2-hora', 'output', false),
  ('banco-ep2-hora-10', 'banco-ep2', 78, 'rapido', '{"frase": "6:30", "opciones": ["half past six", "half past seven"], "correcta": 0, "es": "", "explicacion": "half past = y media.", "segundos": 6}'::jsonb, 'ep2-hora', 'fluidez', false),
  ('banco-ep2-hora-11', 'banco-ep2', 79, 'rapido', '{"frase": "4:00", "opciones": ["four o''clock", "four half"], "correcta": 0, "es": "", "explicacion": "o''clock = en punto.", "segundos": 6}'::jsonb, 'ep2-hora', 'fluidez', false),
  ('banco-ep2-hora-12', 'banco-ep2', 80, 'rapido', '{"frase": "10:45", "opciones": ["a quarter to eleven", "a quarter past ten"], "correcta": 0, "es": "", "explicacion": "a quarter to = menos cuarto.", "segundos": 6}'::jsonb, 'ep2-hora', 'fluidez', false),
  ('examen-ep2-hora-01', 'examen-ep2', 22, 'elegir', '{"frase": "5:15 =", "opciones": ["a quarter past five", "a quarter to five", "five past quarter"], "correcta": 0, "es": "cinco y cuarto", "explicacion": "past = y."}'::jsonb, 'ep2-hora', 'estudio', true),
  ('examen-ep2-hora-02', 'examen-ep2', 23, 'escuchar', '{"opciones": ["It''s half past two.", "It''s half past ten.", "It''s a quarter past two."], "correcta": 0, "audio": "It''s half past two.", "es": "Son las dos y media.", "explicacion": "half past two = 2:30."}'::jsonb, 'ep2-hora', 'input', true),
