  ('banco-ep3-would-like-01', 'banco-ep3', 1, 'comprension', '{"modo": "escuchar", "lineas": [{"en": "Waiter: Would you like something to drink?", "es": "Mesero: ¿Le gustaría algo de tomar?"}, {"en": "Customer: Yes, I''d like a lemonade, please.", "es": "Cliente: Sí, me gustaría una limonada, por favor."}], "pregunta": "What would the customer like?", "pregunta_es": "¿Qué le gustaría al cliente?", "opciones": ["A lemonade", "A coffee", "Water"], "correcta": 0, "explicacion": "I''d like = I would like."}'::jsonb, 'ep3-would-like', 'input', false),
  ('banco-ep3-would-like-02', 'banco-ep3', 2, 'comprension', '{"modo": "leer", "lineas": [{"en": "Would you like to come to my party on Saturday?", "es": "¿Te gustaría venir a mi fiesta el sábado?"}, {"en": "I''d love to! What time?", "es": "¡Me encantaría! ¿A qué hora?"}, {"en": "At eight.", "es": "A las ocho."}], "pregunta": "Is the friend going to the party?", "pregunta_es": "¿El amigo va a la fiesta?", "opciones": ["Yes, he''d love to.", "No, he can''t.", "He doesn''t know."], "correcta": 0, "explicacion": "I''d love to = me encantaría."}'::jsonb, 'ep3-would-like', 'input', false),
  ('banco-ep3-would-like-03', 'banco-ep3', 3, 'decir', '{"es": "Me gustaría un café, por favor.", "respuestas": ["i would like a coffee please", "id like a coffee please"], "mostrar": "I''d like a coffee, please.", "explicacion": "Pedir con cortesía: I''d like…"}'::jsonb, 'ep3-would-like', 'output', false),
  ('banco-ep3-would-like-04', 'banco-ep3', 4, 'decir', '{"es": "¿Te gustaría venir a mi tienda?", "respuestas": ["would you like to come to my store", "would you like to come to my shop"], "mostrar": "Would you like to come to my store?", "explicacion": "Would you like + to + verbo."}'::jsonb, 'ep3-would-like', 'output', false),
  ('banco-ep3-would-like-05', 'banco-ep3', 5, 'libre', '{"pregunta": "Invite a friend to do something this weekend.", "pregunta_es": "Invita a un amigo a hacer algo este fin de semana.", "ejemplo": "Would you like to go to the cinema on Saturday?", "criterio": "Would you like + to + verbo para invitar.", "explicacion": "Would you like + to + verbo para invitar."}'::jsonb, 'ep3-would-like', 'output', false),
  ('banco-ep3-would-like-06', 'banco-ep3', 6, 'rapido', '{"frase": "___ you like tea?", "opciones": ["Would", "Do"], "correcta": 0, "es": "¿Le gustaría un té? (ofrecer)", "explicacion": "Ofrecer → Would you like.", "segundos": 6}'::jsonb, 'ep3-would-like', 'fluidez', false),
  ('banco-ep3-would-like-07', 'banco-ep3', 7, 'rapido', '{"frase": "I''d like ___ go.", "opciones": ["to", "—"], "correcta": 0, "es": "Me gustaría ir.", "explicacion": "would like + to + verbo.", "segundos": 6}'::jsonb, 'ep3-would-like', 'fluidez', false),
  ('banco-ep3-would-like-08', 'banco-ep3', 8, 'rapido', '{"frase": "I''d = I ___", "opciones": ["would", "do"], "correcta": 0, "es": "", "explicacion": "I''d like = I would like.", "segundos": 6}'::jsonb, 'ep3-would-like', 'fluidez', false),
  ('examen-ep3-would-like-01', 'examen-ep3', 1, 'elegir', '{"frase": "___ you like some water?", "opciones": ["Would", "Do", "Are"], "correcta": 0, "es": "¿Le gustaría agua?", "explicacion": "Ofrecer → Would you like."}'::jsonb, 'ep3-would-like', 'estudio', true),
  ('examen-ep3-would-like-02', 'examen-ep3', 2, 'escribir', '{"respuestas": ["i would like to pay by card", "id like to pay by card", "i would like to pay with card", "id like to pay with card"], "mostrar": "I''d like to pay by card.", "es": "Me gustaría pagar con tarjeta.", "explicacion": "I''d like + to + verbo."}'::jsonb, 'ep3-would-like', 'estudio', true),
  ('examen-ep3-would-like-03', 'examen-ep3', 3, 'comprension', '{"modo": "escuchar", "lineas": [{"en": "Would you like a bag?", "es": "¿Quiere una bolsa?"}, {"en": "No, thank you. I''d like a receipt, please.", "es": "No, gracias. Quisiera un recibo, por favor."}], "pregunta": "What does the customer want?", "pregunta_es": "¿Qué quiere el cliente?", "opciones": ["A receipt", "A bag", "Nothing"], "correcta": 0, "explicacion": "I''d like a receipt = quisiera un recibo."}'::jsonb, 'ep3-would-like', 'input', true),
  ('banco-ep3-can-could-01', 'banco-ep3', 9, 'comprension', '{"modo": "escuchar", "lineas": [{"en": "Can you help me?", "es": "¿Me puedes ayudar?"}, {"en": "Sure! What do you need?", "es": "¡Claro! ¿Qué necesitas?"}, {"en": "Could you carry this box, please?", "es": "¿Podrías cargar esta caja, por favor?"}], "pregunta": "What does she need?", "pregunta_es": "¿Qué necesita?", "opciones": ["Help with a box", "A taxi", "Money"], "correcta": 0, "explicacion": "Could you carry…? = ¿Podrías cargar…?"}'::jsonb, 'ep3-can-could', 'input', false),
  ('banco-ep3-can-could-02', 'banco-ep3', 10, 'comprension', '{"modo": "leer", "lineas": [{"en": "My daughter can read, but she can''t swim.", "es": "Mi hija sabe leer, pero no sabe nadar."}, {"en": "She can draw very well.", "es": "Dibuja muy bien."}], "pregunta": "What can''t she do?", "pregunta_es": "¿Qué no sabe hacer?", "opciones": ["Swim", "Read", "Draw"], "correcta": 0, "explicacion": "can''t = no puede / no sabe."}'::jsonb, 'ep3-can-could', 'input', false),
  ('banco-ep3-can-could-03', 'banco-ep3', 11, 'decir', '{"es": "¿Podría ayudarme, por favor?", "respuestas": ["could you help me please", "can you help me please"], "mostrar": "Could you help me, please?", "explicacion": "Could you + verbo + please."}'::jsonb, 'ep3-can-could', 'output', false),
  ('banco-ep3-can-could-04', 'banco-ep3', 12, 'decir', '{"es": "Puedo hablar un poco de inglés.", "respuestas": ["i can speak a little english"], "mostrar": "I can speak a little English.", "explicacion": "can + verbo sin to."}'::jsonb, 'ep3-can-could', 'output', false),
  ('banco-ep3-can-could-05', 'banco-ep3', 13, 'libre', '{"pregunta": "Say two things you can do and one thing you can''t do.", "pregunta_es": "Di dos cosas que sabes hacer y una que no.", "ejemplo": "I can drive and I can sell online, but I can''t swim.", "criterio": "can/can''t + verbo base (sin to, sin -s).", "explicacion": "can/can''t + verbo base (sin to, sin -s)."}'::jsonb, 'ep3-can-could', 'output', false),
