  ('examen-ep3-can-could-02', 'examen-ep3', 5, 'escribir', '{"respuestas": ["can i pay in cash", "could i pay in cash", "can i pay cash", "could i pay cash"], "mostrar": "Can I pay in cash?", "es": "¿Puedo pagar en efectivo?", "explicacion": "Pedir permiso: Can/Could I…?"}'::jsonb, 'ep3-can-could', 'estudio', true),
  ('examen-ep3-can-could-03', 'examen-ep3', 6, 'escuchar', '{"opciones": ["I can''t come tomorrow.", "I can come tomorrow.", "I can''t come today."], "correcta": 0, "audio": "I can''t come tomorrow.", "es": "No puedo venir mañana.", "explicacion": "can''t suena largo y fuerte."}'::jsonb, 'ep3-can-could', 'input', true),
  ('banco-ep3-may-might-01', 'banco-ep3', 17, 'comprension', '{"modo": "escuchar", "lineas": [{"en": "Look at the sky!", "es": "¡Mira el cielo!"}, {"en": "It might rain this afternoon.", "es": "Puede que llueva esta tarde."}, {"en": "Take your umbrella.", "es": "Lleva tu sombrilla."}], "pregunta": "What might happen?", "pregunta_es": "¿Qué puede pasar?", "opciones": ["It might rain.", "It might be sunny.", "It is snowing."], "correcta": 0, "explicacion": "might = puede que (posibilidad)."}'::jsonb, 'ep3-may-might', 'input', false),
  ('banco-ep3-may-might-02', 'banco-ep3', 18, 'comprension', '{"modo": "leer", "lineas": [{"en": "Student: May I come in?", "es": "Estudiante: ¿Puedo pasar?"}, {"en": "Teacher: Yes, of course. Sit down, please.", "es": "Profesor: Sí, claro. Siéntate, por favor."}], "pregunta": "What does the student ask?", "pregunta_es": "¿Qué pide el estudiante?", "opciones": ["Permission to come in", "Help with homework", "To go home"], "correcta": 0, "explicacion": "May I…? = permiso formal."}'::jsonb, 'ep3-may-might', 'input', false),
  ('banco-ep3-may-might-03', 'banco-ep3', 19, 'decir', '{"es": "Puede que llegue tarde.", "respuestas": ["i might be late", "i may be late"], "mostrar": "I might be late.", "explicacion": "might + verbo base."}'::jsonb, 'ep3-may-might', 'output', false),
  ('banco-ep3-may-might-04', 'banco-ep3', 20, 'decir', '{"es": "¿Puedo usar el baño? (formal)", "respuestas": ["may i use the bathroom", "may i use the restroom", "could i use the bathroom", "can i use the bathroom"], "mostrar": "May I use the bathroom?", "explicacion": "Permiso formal: May I…?"}'::jsonb, 'ep3-may-might', 'output', false),
  ('banco-ep3-may-might-05', 'banco-ep3', 21, 'libre', '{"pregunta": "Say two things that might happen this weekend.", "pregunta_es": "Di dos cosas que podrían pasar este fin de semana.", "ejemplo": "I might visit my mother. It might rain on Sunday.", "criterio": "might/may + verbo base.", "explicacion": "might/may + verbo base."}'::jsonb, 'ep3-may-might', 'output', false),
