  ('examen-ep3-may-might-02', 'examen-ep3', 8, 'escribir', '{"respuestas": ["i might go to the cinema", "i may go to the cinema", "i might go to the movies", "i may go to the movies"], "mostrar": "I might go to the cinema.", "es": "Puede que vaya al cine.", "explicacion": "might + verbo base."}'::jsonb, 'ep3-may-might', 'estudio', true),
