  ('banco-ep3-conectores-01', 'banco-ep3', 25, 'comprension', '{"modo": "escuchar", "lineas": [{"en": "I want to buy the shoes, but they are expensive.", "es": "Quiero comprar los zapatos, pero son caros."}, {"en": "So I''m going to buy the cheaper ones.", "es": "Así que voy a comprar los más baratos."}], "pregunta": "Why doesn''t she buy the first shoes?", "pregunta_es": "¿Por qué no compra los primeros zapatos?", "opciones": ["Because they are expensive.", "Because they are ugly.", "Because they are small."], "correcta": 0, "explicacion": "but = pero (contraste); so = así que (resultado)."}'::jsonb, 'ep3-conectores', 'input', false),
  ('banco-ep3-conectores-02', 'banco-ep3', 26, 'comprension', '{"modo": "leer", "lineas": [{"en": "I study English because I want a remote job.", "es": "Estudio inglés porque quiero un trabajo remoto."}, {"en": "I study in the morning or at night.", "es": "Estudio en la mañana o en la noche."}], "pregunta": "Why does he study English?", "pregunta_es": "¿Por qué estudia inglés?", "opciones": ["Because he wants a remote job.", "Because he likes music.", "Because it''s easy."], "correcta": 0, "explicacion": "because = porque."}'::jsonb, 'ep3-conectores', 'input', false),
  ('banco-ep3-conectores-03', 'banco-ep3', 27, 'decir', '{"es": "Estoy cansado, así que me voy a dormir.", "respuestas": ["i am tired so i am going to sleep", "im tired so im going to sleep", "im tired so i am going to sleep", "i am tired so im going to sleep", "im tired so im going to bed", "i am tired so i am going to bed"], "mostrar": "I''m tired, so I''m going to sleep.", "explicacion": "so = así que."}'::jsonb, 'ep3-conectores', 'output', false),
  ('banco-ep3-conectores-04', 'banco-ep3', 28, 'decir', '{"es": "¿Quieres té o café?", "respuestas": ["do you want tea or coffee", "would you like tea or coffee"], "mostrar": "Do you want tea or coffee?", "explicacion": "or = o."}'::jsonb, 'ep3-conectores', 'output', false),
  ('banco-ep3-conectores-05', 'banco-ep3', 29, 'libre', '{"pregunta": "Why do you study English? Use because, but and so.", "pregunta_es": "¿Por qué estudias inglés? Usa because, but y so.", "ejemplo": "I study English because I want a remote job. It''s difficult, but I practice every day, so I''m better now.", "criterio": "Une ideas con because, but, so.", "explicacion": "Une ideas con because, but, so."}'::jsonb, 'ep3-conectores', 'output', false),
